<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'backend-guard'})
useHead({title:'工人采集与审核'})
const {canManageUsers}=useUser(),toast=useToast()
const filters=reactive({enterpriseId:'',deviceId:'',operator:'',mode:'',state:'',classification:'',from:'',to:'',page:1})
watch(()=>[filters.enterpriseId,filters.deviceId,filters.operator,filters.mode,filters.state,filters.classification,filters.from,filters.to],()=>{filters.page=1})
const {data,pending,error,refresh}=await useFetch<any>('/api/admin/worker-production',{query:filters})
const {data:devices}=await useFetch<any>('/api/admin/production-devices')
const companies=computed(()=>Array.from(new Map((devices.value?.rows||[]).map((d:any)=>[d.enterprise_id,{id:d.enterprise_id,name:d.enterprise_name}])).values()) as any[])
const keyword=ref('')
const {data:products}=await useFetch<any>('/api/admin/products',{query:{keyword,pageSize:100,status:1}})
const form=reactive({deviceId:'',productId:'',quantity:1,requestId:crypto.randomUUID()}),busy=ref(false),selected=ref<any>(null)
const detail=ref<any>(null),certificate=ref(''),reason=ref(''),classification=ref('all'),eventPage=ref(1),eventResult=ref('')
const correction=reactive({batchNo:'',produceDate:'',expireDate:''})
const label=(v:string)=>({pending:'待质检',binding:'正在正式绑定',confirmed:'已质检确认并绑定',failed:'质检不合格',binding_error:'绑定异常，请核对',active:'采集中',sealed:'已完整结束',approved:'余码已释放',rejected:'审核退回'}[v]||v)
const cls=(v:string)=>({own:'本厂码',other_enterprise:'本系统其他企业码',not_imported:'未入库内容',unparsed:'未解析'}[v]||v||'-')
async function allocate(){busy.value=true;try{await $fetch('/api/admin/worker-production/pools',{method:'POST',body:{...form,deviceId:Number(form.deviceId),productId:Number(form.productId),quantity:Number(form.quantity)}});form.requestId=crypto.randomUUID();await refresh();toast.add({title:'已预配，设备联网后自动缓存'})}catch(e:any){toast.add({title:e.data?.statusMessage||e.message,color:'error'})}finally{busy.value=false}}
async function loadDetail(){try{detail.value=await $fetch('/api/admin/worker-production/'+selected.value.id,{query:{page:eventPage.value,result:eventResult.value,classification:classification.value}});selected.value={...selected.value,...detail.value.run}}catch(e:any){toast.add({title:e.data?.statusMessage||e.message,color:'error'})}}
async function open(row:any){selected.value=row;certificate.value=row.quality_cert_no||'';reason.value='';classification.value='all';eventPage.value=1;eventResult.value='';await loadDetail();Object.assign(correction,{batchNo:selected.value.context.batchNo,produceDate:selected.value.context.produceDate,expireDate:selected.value.context.expireDate})}
async function review(action:string,decision:string){busy.value=true;try{await $fetch('/api/admin/worker-production/'+selected.value.id+'/review',{method:'POST',body:{action,decision,qualityCertNo:certificate.value,reason:reason.value,correction}});await refresh();await loadDetail();toast.add({title:'处理结果已记录'})}catch(e:any){toast.add({title:e.data?.statusMessage||e.message,color:'error'})}finally{busy.value=false}}
function download(){window.location.href='/api/admin/worker-production/'+selected.value.id+'/download?classification='+classification.value}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{timer=setInterval(()=>{if(!busy.value){refresh();if(selected.value)loadDetail()}},10000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template>
 <div class="space-y-6">
  <div><h1 class="text-2xl font-bold">工人采集与审核</h1><p class="text-muted">设备可以轮流由不同工人登录。已采集、云端已保存、质检绑定分别统计。</p></div>
  <p v-if="!canManageUsers" class="text-error">仅总部管理员或厂家主账号可以管理。</p>
  <template v-else>
   <section class="b-card p-5"><h2 class="mb-4 text-xl font-semibold">按设备、产品预配追溯码</h2><form class="grid gap-4 md:grid-cols-4" @submit.prevent="allocate"><label>设备<select v-model="form.deviceId" required class="mt-2 w-full rounded border p-2"><option value="">请选择</option><option v-for="d in devices?.rows||[]" :key="d.id" :value="String(d.id)">{{ d.enterprise_name }} · {{ d.name }} · {{ d.line_name }}</option></select></label><label>搜索产品<input v-model="keyword" class="mt-2 w-full rounded border p-2" placeholder="产品名称或登记证号"><select v-model="form.productId" required class="mt-2 w-full rounded border p-2"><option value="">请选择产品</option><option v-for="p in products?.rows||[]" :key="p.id" :value="String(p.id)">{{ p.name }} · {{ p.spec_name }} · {{ p.registration_no }}</option></select></label><label>分配数量<input v-model="form.quantity" type="number" min="1" max="100000" required class="mt-2 w-full rounded border p-2"></label><div class="self-end"><UButton type="submit" :loading="busy">固定清单并预配</UButton></div></form><p class="mt-3 text-sm text-muted">每设备每产品只能有一个待用码池。本批范围是开始时全部预配码；结束后未用码须审核，不可凭离线或待上传数量直接释放。</p></section>
   <p v-if="error" class="text-error">加载失败，请刷新核对。</p>
   <section class="b-card overflow-auto p-5"><div class="flex justify-between"><h2 class="text-xl font-semibold">生产与外码采集批次</h2><UButton variant="outline" :loading="pending" @click="refresh()">刷新</UButton></div><div class="mt-4 grid gap-3 md:grid-cols-4">
<label>厂家<select v-model="filters.enterpriseId" class="w-full rounded border p-2"><option value="">全部可见厂家</option><option v-for="c in companies" :key="c.id" :value="String(c.id)">{{ c.name }}</option></select></label><label>设备<select v-model="filters.deviceId" class="w-full rounded border p-2"><option value="">全部设备</option><option v-for="d in devices?.rows||[]" :key="d.id" :value="String(d.id)">{{ d.enterprise_name }} · {{ d.name }}</option></select></label>
<label>工号／姓名<input v-model="filters.operator" class="w-full rounded border p-2"></label>
<label>类型<select v-model="filters.mode" class="w-full rounded border p-2"><option value="">全部</option><option value="production">生产扫码</option><option value="external">外码采集</option></select></label>
<label>同步状态<select v-model="filters.state" class="w-full rounded border p-2"><option value="">全部</option><option value="active">正在采集／待完整上传</option><option value="sealed">完整上传并结束</option></select></label>
<label>开始日期<input v-model="filters.from" type="date" class="w-full rounded border p-2"></label><label>截止日期<input v-model="filters.to" type="date" class="w-full rounded border p-2"></label>
<label>外码分类<select v-model="filters.classification" class="w-full rounded border p-2"><option value="">全部</option><option value="own">本厂码</option><option value="other_enterprise">本系统其他企业码</option><option value="not_imported">未入库内容</option><option value="unparsed">未解析</option></select></label>
</div><table class="mt-4 w-full text-left"><thead><tr><th>类型／产品</th><th>设备／生产线</th><th>生产资料</th><th>领用／采集／待审核</th><th>质检与审核</th><th></th></tr></thead><tbody><tr v-for="r in data?.rows||[]" :key="r.id" class="border-t"><td class="p-3">{{ r.mode==='external'?'外码采集':r.product_name }}</td><td>{{ r.enterprise_name }}<br>{{ r.device_name }} · {{ r.line_name }}</td><td>{{ r.context.batchNo||'-' }}<br>{{ r.context.produceDate||'-' }} → {{ r.context.expireDate||'-' }}</td><td>{{ r.total }} ／ {{ r.collected }} ／ {{ r.remaining }}<br>正式绑定 {{ r.bound }}</td><td>{{ label(r.state) }}<br>{{ r.mode==='production'?label(r.qc_state):'' }}<br>{{ r.mode==='production'?label(r.review_state):'' }}<strong v-if="r.review_needed" class="text-error">资料或人员需核对</strong></td><td><UButton variant="outline" @click="open(r)">明细／处理</UButton></td></tr></tbody></table><div class="mt-4 flex items-center gap-4"><UButton variant="outline" :disabled="filters.page<=1" @click="filters.page--">上一页</UButton><span>{{ filters.page }} 页 · 共 {{ data?.total||0 }} 批</span><UButton variant="outline" :disabled="filters.page*(data?.pageSize||50)>=(data?.total||0)" @click="filters.page++">下一页</UButton></div></section>
   <section class="b-card overflow-auto p-5"><h2 class="mb-3 text-xl font-semibold">已预配码池</h2><table class="w-full text-left"><thead><tr><th>设备</th><th>产品</th><th>数量</th><th>状态</th></tr></thead><tbody><tr v-for="p in data?.pools||[]" :key="p.id" class="border-t"><td class="p-2">{{ p.device_name }}</td><td>{{ p.product_name }}</td><td>{{ p.total }}</td><td>{{ {ready:'待开始',active:'正在生产',review:'剩余码待审核',approved:'已审核'}[p.state]||p.state }}</td></tr></tbody></table></section>
  </template>
  <UModal :open="!!selected" title="批次记录、质检与余码审核" @update:open="v=>{if(!v)selected=null}"><template #body><div v-if="detail" class="space-y-5"><p>{{ selected.device_name }} · {{ selected.context.batchNo||'外码采集' }}</p><div v-if="selected.mode==='production'" class="space-y-4"><p>云端已保存不代表质检合格。实际已采集码始终占用，不能作为剩余码释放。</p><label class="block">质量合格证号<input v-model="certificate" class="mt-2 w-full rounded border p-2"></label><label class="block">核对／审核说明<textarea v-model="reason" class="mt-2 w-full rounded border p-2" /></label><details v-if="selected.state==='sealed'&&selected.qc_state!=='confirmed'"><summary>核对生产日期／批号</summary><p class="my-2 text-sm">仅允许未正式绑定的批次补正。原录入资料、上传收据和补正历史保留；需填写核对说明。</p><label class="block">生产批号<input v-model="correction.batchNo" class="w-full rounded border p-2"></label><div class="my-2 grid grid-cols-2 gap-3"><label>生产日期<input v-model="correction.produceDate" type="date" class="w-full rounded border p-2"></label><label>有效期至<input v-model="correction.expireDate" type="date" class="w-full rounded border p-2"></label></div><UButton :disabled="busy||!reason" variant="outline" @click="review('correct','')">留痕补正</UButton><p class="mt-2 text-sm">原资料：{{ selected.originalContext.batchNo }} · {{ selected.originalContext.produceDate }} → {{ selected.originalContext.expireDate }}</p></details><div class="flex flex-wrap gap-2"><UButton :disabled="busy||selected.state!=='sealed'" @click="review('quality','pass')">确认合格并正式绑定</UButton><UButton color="error" variant="outline" :disabled="busy" @click="review('quality','fail')">质检不合格</UButton></div><p>未扫描码 {{ detail.remaining.length }} 个</p><div class="flex flex-wrap gap-2"><UButton :disabled="busy" @click="review('remaining','approve')">批准剩余码再次使用</UButton><UButton variant="outline" :disabled="busy" @click="review('remaining','reject')">退回审核，继续锁定</UButton></div><details><summary>具体剩余码清单</summary><pre class="max-h-48 overflow-auto text-xs">{{ detail.remaining.map((c:any)=>c.code).join('\n') }}</pre></details></div><div v-else><label>TXT分类<select v-model="classification" class="m-2 rounded border p-2"><option value="all">全部</option><option value="own">本厂码</option><option value="other_enterprise">本系统其他企业码</option><option value="not_imported">未入库内容</option><option value="unparsed">未解析</option></select></label><UButton @click="download">下载去重原文 TXT</UButton></div><h3 class="font-semibold">工人会话与交班</h3><p v-if="selected.deviceSnapshot">本批设备：{{ selected.deviceSnapshot.enterpriseName }} · {{ selected.deviceSnapshot.name }} · {{ selected.deviceSnapshot.lineName }}</p><p v-for="s in detail.sessions" :key="s.id">{{ (typeof s.identity_json==='string'?JSON.parse(s.identity_json):s.identity_json).name }} · {{ s.state }} · 收到 {{ s.last_sequence }} 条</p><h3 class="font-semibold">采集原文与同步收据</h3><div class="flex flex-wrap items-center gap-3"><select v-model="eventResult" class="rounded border p-2" @change="eventPage=1;loadDetail()"><option value="">全部记录</option><option value="saved">云端已保存</option><option value="duplicate">重复</option><option value="exception">异常</option></select><UButton variant="outline" :disabled="eventPage<=1" @click="eventPage--;loadDetail()">上一页</UButton><span>{{ eventPage }} 页／{{ detail.total }} 条</span><UButton variant="outline" :disabled="eventPage*detail.pageSize>=detail.total" @click="eventPage++;loadDetail()">下一页</UButton><UButton variant="outline" @click="eventPage=1;loadDetail()">应用分类</UButton></div><div v-for="e in detail.rows" :key="e.id" class="border-t py-2 text-sm"><p>{{ (typeof e.identity_json==='string'?JSON.parse(e.identity_json):e.identity_json).name }} · {{ e.captured_at }} · {{ e.result_state }} · {{ cls(e.classification) }}</p><code class="break-all">{{ e.raw_code }}</code><p>{{ e.reason }}</p></div><details><summary>审核与交班历史</summary><div v-for="a in detail.audits" :key="a.id" class="border-t py-2 text-sm"><p>{{ a.created_at }} · {{ a.actor_name||'设备' }} · {{ a.action }}</p><pre class="whitespace-pre-wrap break-all">{{ JSON.stringify(typeof a.detail==='string'?JSON.parse(a.detail):a.detail,null,2) }}</pre></div></details></div></template></UModal>
 </div>
</template>
